void mark(std::string value){stage=std::move(value);std::ofstream(root/"stage.txt")<<stage<<'\n';std::cout<<"STAGE "<<stage<<std::endl;}
void done(Document &d){if(!d.wait_asset(std::chrono::seconds(120))||!d.wait_native_stroke(std::chrono::seconds(120))||!d.wait_mesh(std::chrono::seconds(120))||!d.frame().state->error.empty())throw std::runtime_error("Commutation endpoint "+stage+": "+d.frame().state->error);}
